"""Calculate monthly cleaning-service salaries from the supplied CSV files."""

import ast
import csv
import json
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(filename: str) -> list[dict[str, str]]:
    with (DATASET / filename).open(encoding="utf-8", newline="") as file:
        return list(csv.DictReader(file))


def _task_ids(value: str) -> list[int]:
    """Repair missing outer brackets without inventing any task identifiers."""
    value = value.strip()
    if not value.startswith("["):
        value = "[" + value
    if not value.endswith("]"):
        value += "]"
    try:
        parsed = ast.literal_eval(value)
    except (ValueError, SyntaxError):
        return []
    if not isinstance(parsed, list):
        return []
    return [item for item in parsed if type(item) is int]


def _period_start(day: date, weekday: int) -> date:
    """A billing month starts on its first occurrence of the anchor weekday."""
    first = day.replace(day=1)
    start = first + timedelta(days=(weekday - first.weekday()) % 7)
    if day < start:
        first = (first - timedelta(days=1)).replace(day=1)
        start = first + timedelta(days=(weekday - first.weekday()) % 7)
    return start


def answer() -> dict[str, list[int]]:
    employees = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in _read_csv("employees.csv")
    }
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _read_csv("tasks.csv")
    }

    shifts = []
    seen = set()
    for row in _read_csv("timesheet.csv"):
        pesel = row["employee_id"]
        # Unknown identities cannot be safely assigned to a registered employee.
        if pesel not in employees:
            continue
        try:
            day = date.fromisoformat(row["date"])
            hours = Decimal(row["hours_worked"])
        except (ValueError, InvalidOperation):
            continue
        if not hours.is_finite() or not Decimal(0) <= hours <= Decimal(24):
            continue

        # Repeated records have different surrogate IDs but identical shift data.
        signature = tuple(value for key, value in row.items() if key != "id")
        if signature in seen:
            continue
        seen.add(signature)

        # The catalog is authoritative: unknown tasks contribute no bonus.
        # This also corrects the negative bonuses attached to empty task lists.
        bonus = sum(
            (task_pay.get(task_id, Decimal(0))
             for task_id in _task_ids(row["performed_tasks"])),
            Decimal(0),
        )
        shifts.append((pesel, day, hours, bonus))

    if not shifts:
        return {pesel: [] for pesel in employees}

    weekday = min(day for _, day, _, _ in shifts).weekday()
    totals = defaultdict(lambda: Decimal(0))
    periods = set()
    for pesel, day, hours, bonus in shifts:
        period = _period_start(day, weekday)
        periods.add(period)
        totals[pesel, period] += hours * employees[pesel] + bonus

    ordered_periods = sorted(periods)
    return {
        pesel: [
            int(totals[pesel, period].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for period in ordered_periods
        ]
        for pesel in employees
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as file:
        json.dump(answer(), file, default=list)
